def minimumChanges(s, k):
    n = len(s)
    INF = float('inf')
    # cost[i][j] = min letter changes to make s[i..j] a semi-palindrome.
    # A length-1 substring has no valid divisor, so it can never be a semi-palindrome.
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            L = j - i + 1
            if L == 1:
                cost[i][j] = INF
                continue
            best = INF
            for d in range(1, L):
                if L % d:
                    continue
                m = L // d
                tot = 0
                for r in range(d):  # group of positions i+r, i+r+d, ...
                    lo, hi = 0, m - 1
                    while lo < hi:
                        if s[i + r + lo * d] != s[i + r + hi * d]:
                            tot += 1
                        lo += 1
                        hi -= 1
                if tot < best:
                    best = tot
            cost[i][j] = best

    # dp[t][i] = min changes partitioning s[0..i-1] into t semi-palindromes.
    dp = [[INF] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
    for t in range(1, k + 1):
        for i in range(1, n + 1):
            for j in range(0, i):
                if dp[t - 1][j] < INF and cost[j][i - 1] < INF:
                    v = dp[t - 1][j] + cost[j][i - 1]
                    if v < dp[t][i]:
                        dp[t][i] = v
    return dp[k][n]
